import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/troubleshooting.md","filePath":"zh-HK/user-guide/troubleshooting.md","lastUpdated":1785993908000}'),s={name:"zh-HK/user-guide/troubleshooting.md"};function n(i,t,l,h,g,d){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><h2 id="全局熱鍵沒有反應" tabindex="-1">全局熱鍵沒有反應 <a class="header-anchor" href="#全局熱鍵沒有反應" aria-label="Permalink to &quot;全局熱鍵沒有反應&quot;">​</a></h2><ol><li>先看<strong>設定 → 運行狀態</strong>——如果後臺服務沒有運行，重裝或重啓它通常能解決索引相關的問題，但呼出熱鍵本身是由 App 處理程序處理的，不是服務，所以這只是一個次要排查項。</li><li>如果當前前臺應用是以系統管理員身份運行的，而 Lertaro 不是，Windows 會阻止低權限處理程序向它發送輸入。Lertaro 的後臺熱鍵監聽處理程序會在你的帳戶是系統管理員時自動提權——不需要開關，也不會彈 UAC 視窗。如果熱鍵還是打不到已提權的視窗，先去<a href="./settings/service-status.html"><strong>設定 → 運行狀態</strong></a>確認後臺服務在運行，因為提權的監聽處理程序是由它拉起的。如果你的帳戶本身不是系統管理員，這個限制沒有辦法繞過——Windows 不允許低權限處理程序向高權限處理程序發送輸入。</li><li>檢查<a href="./settings/hotkeys-page.html#process-blacklist">處理程序黑名單</a>——如果前臺應用的可執行檔案名被（有意或無意地）加入了黑名單，Lertaro 的全局熱鍵在它處於前臺時會被刻意放行、不做攔截。</li><li>如果前臺應用是真正全屏（鋪滿了整個顯示器），Lertaro 預設會自動放行它的熱鍵——為了不和全屏遊戲搶鍵盤。如果你設定的組合鍵不會跟全屏應用自己用到的按鍵衝突，可以在<strong>設定 → 熱鍵 → 顯示/隱藏快速搜尋</strong>旁邊打開<strong>全屏應用聚焦時仍然響應</strong>，讓它在全屏下也照常生效。不想開這個開關的話，切出全屏（Alt+Tab），或者把應用改成視窗化/無邊框視窗模式而不是獨佔全屏，也能避免這個情況。</li></ol><h2 id="搜尋結果看起來過時了" tabindex="-1">搜尋結果看起來過時了 <a class="header-anchor" href="#搜尋結果看起來過時了" aria-label="Permalink to &quot;搜尋結果看起來過時了&quot;">​</a></h2><p>NTFS 和 ReFS 磁碟是通過 USN 日誌近乎實時更新的；其他本地檔案系統（FAT32、exFAT 等）沒有日誌可用，改為直接監聽檔案系統變化，同樣是持續實時的。如果還是有內容看起來不對（剛創建的檔案沒出現，或者已刪除的檔案還在），可以到<strong>設定 → 索引 → 本地磁碟機</strong>（或<strong>網絡磁碟機</strong>）對相應磁碟執行<strong>重建索引</strong>。</p><h2 id="網絡磁碟機好像一直不刷新" tabindex="-1">網絡磁碟機好像一直不刷新 <a class="header-anchor" href="#網絡磁碟機好像一直不刷新" aria-label="Permalink to &quot;網絡磁碟機好像一直不刷新&quot;">​</a></h2><p>網絡共享沒有本地 NTFS 卷那種可以監聽的變更日誌，所以是按計劃定時重新掃描的。到<strong>設定 → 索引 → 網絡磁碟機</strong>檢查該磁碟機的<strong>刷新模式</strong>——如果是<strong>手動</strong>，就不會自動更新，改成定時刷新，或者直接點<strong>重建索引</strong>手動刷新一次。對於 NAS SMB 共享下的特殊符號鏈接或遞歸路徑，掃描引擎已內置環路檢測，避免重複循環。</p><h2 id="預覽視窗顯示不對-被裁切" tabindex="-1">預覽視窗顯示不對/被裁切 <a class="header-anchor" href="#預覽視窗顯示不對-被裁切" aria-label="Permalink to &quot;預覽視窗顯示不對/被裁切&quot;">​</a></h2><p>理論上不應該發生——Lertaro 會自動把 QuickLook 預覽視窗的位置和大小鉗制在當前顯示器的可用區域內。如果還是看到裁切，可以先到<strong>設定 → 通用 → 預覽視窗 → 重置預覽視窗設定</strong>排除掉手動設定了異常寬高值的可能，並確認使用的是最新版本。</p><h2 id="某個檔案-資料夾完全搜不到" tabindex="-1">某個檔案/資料夾完全搜不到 <a class="header-anchor" href="#某個檔案-資料夾完全搜不到" aria-label="Permalink to &quot;某個檔案/資料夾完全搜不到&quot;">​</a></h2><ul><li>檢查它是否被排除了——<strong>設定 → 索引 → 排除規則</strong>支援精確路徑、glob 通配符和正則表達式三種方式，任何一種都有可能無意中命中它。</li><li>檢查它所在的磁碟是否在<strong>設定 → 索引 → 本地/網絡磁碟機</strong>裏被啓用。</li></ul><h2 id="在內聯視窗裏用輸入法打中文-或其他需要候選框的語言-不生效" tabindex="-1">在內聯視窗裏用輸入法打中文（或其他需要候選框的語言）不生效 <a class="header-anchor" href="#在內聯視窗裏用輸入法打中文-或其他需要候選框的語言-不生效" aria-label="Permalink to &quot;在內聯視窗裏用輸入法打中文（或其他需要候選框的語言）不生效&quot;">​</a></h2><p><a href="./getting-started.html#三種視窗">內聯視窗</a>故意不會從它嵌入的那個視窗手裏搶走真正的鍵盤焦點——這樣你關掉它時才能乾淨利落地回到剛才的狀態，不會有焦點閃爍。但輸入法的組合過程（候選詞列表，以及最終上屏的字元）只會發生在<strong>真正持有焦點</strong>的那個視窗上，而這個視窗始終是被嵌入的目標應用，不是 Lertaro——所以沒有任何消息是 Lertaro 能攔截到、從而捕獲你打的內容的。這是內聯視窗工作方式帶來的結構性限制，不是 bug。</p><p>兩個辦法：</p><ul><li>直接打拼音字母（不需要真的彈出候選框）——Lertaro 會自動按拼音匹配中文檔案名，見<a href="./search-syntax.html#中文檔案名-拼音別名">搜尋語法</a>。</li><li>改用<a href="./getting-started.html#三種視窗">快速視窗</a>（預設雙擊 <code>Ctrl</code> 呼出）——它是一個真正獲得焦點的視窗，輸入法在裏面能正常工作。</li></ul><h2 id="還是沒解決" tabindex="-1">還是沒解決？ <a class="header-anchor" href="#還是沒解決" aria-label="Permalink to &quot;還是沒解決？&quot;">​</a></h2><p>在提交 GitHub issue 之前，先看看 <strong><a href="./settings/service-status.html">設定 → 運行狀態</a></strong> 裏 <strong>Service</strong>、<strong>App</strong>、<strong>Hook</strong> 三個日誌 Tab——搜尋框可以按關鍵詞過濾，等級下拉式方塊可以按嚴重程度過濾。</p>',17)])])}const p=a(s,[["render",n]]);export{c as __pageData,p as default};
